:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --ink: #1c2333;
  --muted: #6b7280;
  --line: #e5e7eb;
  --brand: #3b5bdb;
  --brand-ink: #ffffff;
  --danger: #c92a2a;
  --warn-bg: #fff4e6;
  --warn-ink: #9c4221;
  --ok-bg: #ebfbee;
  --ok-ink: #2b8a3e;
  --err-bg: #fff5f5;
  --err-ink: #c92a2a;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}

.app { max-width: 760px; margin: 0 auto; padding: 2rem 1rem 4rem; }
.app__header { margin-bottom: 1.5rem; }
.app__header h1 { margin: 0; font-size: 1.9rem; }
.app__subtitle { margin: 0.25rem 0 0; color: var(--muted); }

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
}
.card h2 { margin: 0 0 0.9rem; font-size: 1.1rem; }

.form__row { display: flex; flex-direction: column; margin-bottom: 0.75rem; }
.form__row label { font-size: 0.85rem; font-weight: 600; margin-bottom: 0.25rem; }
.hint { font-weight: 400; color: var(--muted); }
.req { color: var(--danger); }

input[type="text"], input[type="search"] {
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 0.95rem;
  width: 100%;
}
input:focus { outline: 2px solid var(--brand); border-color: var(--brand); }

.form__actions { display: flex; gap: 0.5rem; justify-content: flex-end; margin-top: 0.25rem; }

.btn {
  padding: 0.5rem 0.9rem;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 8px;
  font-size: 0.9rem;
  cursor: pointer;
}
.btn:hover { background: #f8f9fb; }
.btn--primary { background: var(--brand); color: var(--brand-ink); border-color: var(--brand); }
.btn--primary:hover { filter: brightness(1.05); }
.btn--link { border: none; background: none; color: var(--brand); padding: 0.25rem; }
.btn--danger { color: var(--danger); border-color: #f1c7c7; }

.message { margin: 0.6rem 0 0; font-size: 0.9rem; min-height: 1.2em; }
.message--error { color: var(--err-ink); background: var(--err-bg); padding: 0.5rem 0.7rem; border-radius: 8px; }
.message--ok { color: var(--ok-ink); background: var(--ok-bg); padding: 0.5rem 0.7rem; border-radius: 8px; }
.message--warn { color: var(--warn-ink); background: var(--warn-bg); padding: 0.5rem 0.7rem; border-radius: 8px; }

.toolbar { display: flex; gap: 0.75rem; align-items: center; margin-bottom: 0.75rem; flex-wrap: wrap; }
.toolbar__search { flex: 1; min-width: 200px; }
.active-filter { font-size: 0.85rem; color: var(--muted); display: flex; align-items: center; gap: 0.25rem; }

.tag-cloud { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-bottom: 1rem; }
.tag-chip {
  font-size: 0.78rem;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: #f8f9fb;
  cursor: pointer;
}
.tag-chip:hover { border-color: var(--brand); color: var(--brand); }
.tag-chip--active { background: var(--brand); color: #fff; border-color: var(--brand); }

.list { display: flex; flex-direction: column; gap: 0.75rem; }

.bookmark {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 0.9rem 1rem;
}
.bookmark__top { display: flex; justify-content: space-between; gap: 0.75rem; align-items: baseline; }
.bookmark__title { font-weight: 600; font-size: 1rem; }
.bookmark__title a { color: var(--ink); text-decoration: none; }
.bookmark__title a:hover { color: var(--brand); text-decoration: underline; }
.bookmark__url { font-size: 0.82rem; color: var(--muted); word-break: break-all; }
.bookmark__url a { color: var(--muted); }
.bookmark__note { font-size: 0.88rem; margin: 0.4rem 0 0; }
.bookmark__tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: 0.5rem; }
.bookmark__actions { display: flex; gap: 0.4rem; flex-shrink: 0; }

.empty {
  text-align: center;
  color: var(--muted);
  padding: 2rem 1rem;
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

.dialog { border: none; border-radius: var(--radius); padding: 1.25rem; max-width: 460px; width: 90%; }
.dialog::backdrop { background: rgba(0, 0, 0, 0.35); }
.readonly-url { margin: 0; font-size: 0.85rem; color: var(--muted); word-break: break-all; }

